# Generated by build.py from recipe.yml for recipe https-tunnel-through-a-proxy. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList '--proxy', 'http://127.0.0.1:8081/', '--proxy', 'https://127.0.0.1:8082/', '--cert', 'server.pem', '--key', 'server.key', '-v', '--log-file', 'proxy.log' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --cacert server.pem -x http://127.0.0.1:8081/ https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0; Stop-Process $server1 }
